const $=s=>document.querySelector(s);
const DEFAULT_WATERMARK='data:image/jpeg;base64,';
const state={items:[],current:-1,bitmap:null,view:null,drag:null,detector:null,personModel:null,aiTried:false,originalsRoot:null,nasRoot:null,sourceFolderName:'',watermarkSource:null};
const A4={portrait:{w:2480,h:3508,label:'A4 na výšku'},landscape:{w:3508,h:2480,label:'A4 na šířku'}};

$('#backBtn').onclick=()=>window.desktopFiles?.close();
$('#files').onchange=()=>setFiles([...$('#files').files]);
$('#analyze').onclick=analyzeAll;
$('#saveOne').onclick=saveCurrent;
$('#saveAll').onclick=saveAll;
$('#setOriginalsFolder').onclick=()=>chooseDestination('originals');
$('#setNasFolder').onclick=()=>chooseDestination('nas');
$('#watermarkFile').onchange=chooseWatermark;
$('#resetCrop').onclick=()=>analyzeOne(state.current,true);
$('#quality').oninput=()=>$('#qualityValue').textContent=$('#quality').value+' %';
$('#zoom').oninput=()=>{const item=current();if(!item?.crop)return;setZoom(item,+$('#zoom').value);renderEditor()};
$('#orientation').onchange=()=>{state.items.forEach(x=>{x.crop=null;x.status='waiting'});renderList();$('#saveAll').disabled=true;if(state.items.length)analyzeAll()};

function setStatus(text){$('#status').textContent=text}
function current(){return state.items[state.current]||null}
function safeName(name){return name.replace(/\.[^.]+$/,'').replace(/[\\/:*?"<>|]+/g,'_').trim()||'fotografie'}
function safeFolderName(name){return String(name||'Fotografie').replace(/[\\/:*?"<>|]+/g,'_').replace(/[. ]+$/,'').trim()||'Fotografie'}
function outputName(item){const cleaned=item.file.name.replace(/[\\/:*?"<>|]+/g,'_').trim()||'fotografie.jpg';return /\.jpe?g$/i.test(cleaned)?cleaned:safeName(cleaned)+'.jpg'}
function formatBytes(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.round(n/1024)+' kB'}

function openHandleDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('a4-crop-settings',1);req.onupgradeneeded=()=>req.result.createObjectStore('handles');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function storeDirectory(handle,key){const db=await openHandleDb();await new Promise((resolve,reject)=>{const tx=db.transaction('handles','readwrite');tx.objectStore('handles').put(handle,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function readDirectory(key){const db=await openHandleDb(),handle=await new Promise((resolve,reject)=>{const tx=db.transaction('handles','readonly'),req=tx.objectStore('handles').get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)});db.close();return handle}
async function storeWatermark(blob){const db=await openHandleDb();await new Promise((resolve,reject)=>{const tx=db.transaction('handles','readwrite');tx.objectStore('handles').put(blob,'watermark-logo');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function readWatermark(){const db=await openHandleDb(),blob=await new Promise((resolve,reject)=>{const tx=db.transaction('handles','readonly'),req=tx.objectStore('handles').get('watermark-logo');req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)});db.close();return blob}
function destinationReady(type,handle,needsPermission=false){
  const isNas=type==='nas',stateKey=isNas?'nasRoot':'originalsRoot',statusId=isNas?'#nasFolderState':'#originalsFolderState';state[stateKey]=handle;
  $(statusId).textContent=(needsPermission?'Zapamatováno, znovu povolte: ':'Vybraná složka: ')+handle.name;
}
async function restoreDestinations(){
  if(window.desktopFiles){$('#originalsFolderState').textContent='Vyberte cílovou složku.';$('#nasFolderState').textContent='Vyberte cílovou složku.';return}
  if(!('showDirectoryPicker' in window)){const message='Přímé ukládání vyžaduje Chrome nebo Edge a otevření aplikace přes zabezpečenou adresu HTTPS.';$('#originalsFolderState').textContent=message;$('#nasFolderState').textContent=message;setStatus(message);return}
  for(const type of ['originals','nas'])try{const handle=await readDirectory(type+'-root');if(!handle)continue;const permission=await handle.queryPermission({mode:'readwrite'});destinationReady(type,handle,permission!=='granted')}catch(_){/* první spuštění */}
}
async function chooseDestination(type){
  if(window.desktopFiles){const selected=await window.desktopFiles.chooseDirectory();if(!selected)return null;const stateKey=type==='nas'?'nasRoot':'originalsRoot',statusId=type==='nas'?'#nasFolderState':'#originalsFolderState';state[stateKey]=selected;$(statusId).textContent='Vybraná složka: '+selected;return selected}
  if(!('showDirectoryPicker' in window)){const message='Cílovou složku nelze otevřít. Použijte Chrome nebo Edge a zabezpečenou adresu HTTPS.';$('#originalsFolderState').textContent=message;$('#nasFolderState').textContent=message;setStatus(message);alert(message);return null}
  try{const handle=await showDirectoryPicker({id:type==='nas'?'fotozababku-nas':'fotozababku-originals',mode:'readwrite',startIn:'pictures'});await storeDirectory(handle,type+'-root');destinationReady(type,handle);return handle}catch(err){if(err.name!=='AbortError')alert('Složku se nepodařilo povolit.');return null}
}
async function ensureDestination(type){
  const stateKey=type==='nas'?'nasRoot':'originalsRoot';let handle=state[stateKey];if(!handle)return await chooseDestination(type);
  if(window.desktopFiles)return handle;
  let permission=await handle.queryPermission({mode:'readwrite'});if(permission!=='granted')permission=await handle.requestPermission({mode:'readwrite'});if(permission!=='granted'){alert(type==='nas'?'Ukládání do vybrané složky na NAS nebylo povoleno.':'Ukládání upravených originálů nebylo povoleno.');return null}destinationReady(type,handle);return handle
}
async function writeToDirectory(dir,item,blob){if(window.desktopFiles){await window.desktopFiles.writeFile(dir,'',outputName(item),await blob.arrayBuffer());return}const handle=await dir.getFileHandle(outputName(item),{create:true}),writer=await handle.createWritable();await writer.write(blob);await writer.close()}

async function chooseWatermark(){
  const file=$('#watermarkFile').files[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/i.test(file.type))return alert('Vyberte logo ve formátu PNG, JPG nebo WebP.');
  try{const bitmap=await loadBitmap(file);bitmap.close?.();state.watermarkSource=file;await storeWatermark(file);$('#watermarkState').textContent='Vlastní logo uloženo: '+file.name;setStatus('Nové logo vodoznaku je připraveno a aplikace si je zapamatovala.')}catch(_){alert('Vybrané logo nelze načíst.')}
}
async function restoreWatermark(){
  try{const saved=await readWatermark();if(saved){state.watermarkSource=saved;$('#watermarkState').textContent='Vlastní logo vodoznaku je uložené.';return}}
  catch(_){/* první spuštění */}
  try{state.watermarkSource=await loadImageAsset(DEFAULT_WATERMARK);$('#watermarkState').textContent='Použije se přiložené logo European Hockey Kingdom.'}
  catch(_){$('#watermarkState').textContent='Logo se nepodařilo načíst – vyberte jej ručně.'}
}
async function getOutputFolders(){
  if(!state.sourceFolderName){alert('Nejdříve vyberte zdrojovou složku fotografií.');return null}
  if(window.desktopFiles){const originalsRoot=await ensureDestination('originals');if(!originalsRoot)return null;const nasRoot=await ensureDestination('nas');if(!nasRoot)return null;if(originalsRoot===nasRoot){alert('Vyberte dvě rozdílné cílové složky.');return null}const folderName=safeFolderName(state.sourceFolderName);return{originals:originalsRoot+'|'+folderName,previews:nasRoot+'|'+folderName}}
  if(!('showDirectoryPicker' in window)){alert('Přímé ukládání vyžaduje Chrome nebo Edge a otevření aplikace přes zabezpečenou adresu HTTPS.');return null}
  const originalsRoot=await ensureDestination('originals');if(!originalsRoot)return null;
  const nasRoot=await ensureDestination('nas');if(!nasRoot)return null;
  if(originalsRoot.isSameEntry&&await originalsRoot.isSameEntry(nasRoot)){alert('Pro upravené originály a náhledy vyberte dvě rozdílné cílové složky.');return null}
  const folderName=safeFolderName(state.sourceFolderName);
  const originals=await originalsRoot.getDirectoryHandle(folderName,{create:true});
  const previews=await nasRoot.getDirectoryHandle(folderName,{create:true});
  return{originals,previews};
}

function setFiles(files){
  files=files.filter(file=>/^image\/(jpeg|png|webp)$/i.test(file.type));
  state.items.forEach(x=>URL.revokeObjectURL(x.url));if(state.bitmap?.close)state.bitmap.close();state.bitmap=null;
  const roots=[...new Set(files.map(file=>(file.webkitRelativePath||file.name).split('/')[0]))];state.sourceFolderName=roots.length?safeFolderName(roots[0]):'';
  state.items=files.map(file=>({file,url:URL.createObjectURL(file),status:'waiting',crop:null,focus:null,method:'Čeká na analýzu'}));state.current=files.length?0:-1;
  if(state.originalsRoot)destinationReady('originals',state.originalsRoot);if(state.nasRoot)destinationReady('nas',state.nasRoot);
  renderList();$('#saveAll').disabled=true;setStatus(files.length?`Zdrojová složka: ${state.sourceFolderName}. Vybráno fotografií: ${files.length}. Výsledky se uloží přímo do dvou zvolených cílových složek.`:'Ve vybrané složce nebyly nalezeny podporované fotografie.');
  if(files.length){selectItem(0);setTimeout(()=>analyzeAll(),0)}else{$('#editor').hidden=true;$('#emptyStage').hidden=false}
}

function renderList(){
  if(!state.items.length){$('#fileList').innerHTML='<div class="empty">Zatím nebyly vybrány žádné fotografie.</div>';return}
  $('#fileList').innerHTML=state.items.map((item,i)=>`<button class="file ${i===state.current?'active':''} ${item.status==='ok'?'ok':item.status==='error'?'error':''}" data-index="${i}"><img class="thumb" src="${item.url}" alt=""><span><span class="filename">${escapeHtml(item.file.name)}</span><span class="small">${formatBytes(item.file.size)}<br>${escapeHtml(item.method)}</span></span></button>`).join('');
  document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>selectItem(+b.dataset.index));
}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

async function loadBitmap(file){
  try{return await createImageBitmap(file,{imageOrientation:'from-image'})}catch(_){return await createImageBitmap(file)}
}
function loadImageAsset(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
async function selectItem(index){
  if(index<0||index>=state.items.length)return;state.current=index;renderList();
  if(state.bitmap?.close)state.bitmap.close();state.bitmap=null;
  try{state.bitmap=await loadBitmap(current().file);$('#emptyStage').hidden=true;$('#editor').hidden=false;syncEditor();renderEditor()}
  catch(_){current().status='error';current().method='Soubor nelze otevřít';renderList();setStatus('Vybranou fotografii se nepodařilo otevřít.')}
}
function syncEditor(){
  const item=current();if(!item)return;$('#zoom').value=item.crop?.zoom||1;$('#methodBadge').textContent=item.method;
  const target=item.target||orientationFor(state.bitmap);const t=A4[target];
  $('#resolutionWarning').textContent=state.bitmap&&(state.bitmap.width<t.w||state.bitmap.height<t.h)?`Upozornění: zdroj má ${state.bitmap.width} × ${state.bitmap.height} px a bude při výstupu zvětšen.`:'';
}

function orientationFor(bitmap){const choice=$('#orientation').value;if(choice!=='auto')return choice;return bitmap.width>=bitmap.height?'landscape':'portrait'}
function largestCrop(w,h,ratio){if(w/h>ratio)return{w:h*ratio,h};return{w,h:w/ratio}}
function clampCrop(c,w,h){c.w=Math.min(c.w,w);c.h=Math.min(c.h,h);c.x=Math.max(0,Math.min(w-c.w,c.x));c.y=Math.max(0,Math.min(h-c.h,c.y));return c}
function setCropAround(item,cx,cy,zoom=1){
  const target=A4[item.target],base=largestCrop(item.width,item.height,target.w/target.h);item.base=base;
  const w=base.w/zoom,h=base.h/zoom;item.crop=clampCrop({x:cx-w/2,y:cy-h/2,w,h,zoom},item.width,item.height);
}
function setZoom(item,zoom){const cx=item.crop.x+item.crop.w/2,cy=item.crop.y+item.crop.h/2,w=item.base.w/zoom,h=item.base.h/zoom;item.crop=clampCrop({x:cx-w/2,y:cy-h/2,w,h,zoom},item.width,item.height)}
function setCropForBox(item,box){
  const ratio=A4[item.target].w/A4[item.target].h,b={x:Math.max(0,box.x-box.w*.10),y:Math.max(0,box.y-box.h*.06),w:box.w*1.20,h:box.h*1.14};
  b.w=Math.min(item.width-b.x,b.w);b.h=Math.min(item.height-b.y,b.h);let w=b.w,h=b.h;
  if(w/h>ratio)h=w/ratio;else w=h*ratio;const fit=Math.min(1,item.width/w,item.height/h);w*=fit;h*=fit;
  const cx=b.x+b.w/2,cy=b.y+b.h/2;item.base={w,h};item.crop=clampCrop({x:cx-w/2,y:cy-h/2,w,h,zoom:1},item.width,item.height);
}

function loadScript(src){return new Promise((resolve,reject)=>{const old=[...document.scripts].find(x=>x.src===src);if(old){if(old.dataset.loaded)return resolve();old.addEventListener('load',resolve,{once:true});old.addEventListener('error',reject,{once:true});return}const s=document.createElement('script');s.src=src;s.crossOrigin='anonymous';s.dataset.loaded='';s.onload=()=>{s.dataset.loaded='1';resolve()};s.onerror=()=>reject(new Error('script'));document.head.appendChild(s)})}
async function ensureAI(){
  if(state.personModel||state.aiTried)return !!state.personModel;state.aiTried=true;$('#aiState').textContent='Načítám AI model pro rozpoznání celých postav…';
  try{await loadScript('https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js');await tf.ready();await loadScript('https://cdn.jsdelivr.net/npm/@tensorflow-models/coco-ssd@2.2.3/dist/coco-ssd.min.js');state.personModel=await cocoSsd.load({base:'lite_mobilenet_v2'});$('#aiState').textContent='AI rozpoznání celých postav je připraveno.';return true}
  catch(_){$('#aiState').textContent='AI model se nepodařilo načíst – použije se místní záložní analýza ostrosti.';return false}
}

async function analyzeAll(){
  if(!state.items.length)return alert('Nejdříve vyberte fotografie.');$('#analyze').disabled=true;$('#saveAll').disabled=true;
  setStatus('Připravuji rozpoznání postav…');await ensureAI();
  let ok=0;for(let i=0;i<state.items.length;i++){setStatus(`Analyzuji fotografii ${i+1} z ${state.items.length}: ${state.items[i].file.name}`);if(await analyzeOne(i,false))ok++;await new Promise(r=>setTimeout(r,0));}
  $('#analyze').disabled=false;$('#saveAll').disabled=ok===0;setStatus(`Hotovo. Automatický ořez byl připraven pro ${ok} z ${state.items.length} fotografií. Při uložení se automaticky použije úprava Zkusím štěstí; modrý rámeček lze případně upravit.`);await selectItem(Math.max(0,state.items.findIndex(x=>x.status==='ok')));
}
async function analyzeOne(index,show){
  const item=state.items[index];if(!item)return false;let bitmap=null;
  try{
    bitmap=await loadBitmap(item.file);item.width=bitmap.width;item.height=bitmap.height;item.target=orientationFor(bitmap);
    const found=await findFocus(bitmap);item.focus={x:found.x*bitmap.width,y:found.y*bitmap.height};item.method=found.method;item.sharpness=found.sharpness||0;item.status='ok';
    item.personBox=found.box?{x:found.box.x*bitmap.width,y:found.box.y*bitmap.height,w:found.box.w*bitmap.width,h:found.box.h*bitmap.height}:null;
    if(item.personBox)setCropForBox(item,item.personBox);else setCropAround(item,item.focus.x,item.focus.y,1);renderList();
    if(show||index===state.current){if(index!==state.current)await selectItem(index);else{if(state.bitmap?.close)state.bitmap.close();state.bitmap=bitmap;bitmap=null;syncEditor();renderEditor()}}
    return true;
  }catch(err){item.status='error';item.method='Analýza se nezdařila';renderList();return false}finally{if(bitmap?.close)bitmap.close()}
}

async function findFocus(bitmap){
  const max=900,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),w=Math.max(80,Math.round(bitmap.width*scale)),h=Math.max(80,Math.round(bitmap.height*scale));
  const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,w,h);const img=ctx.getImageData(0,0,w,h),gray=new Uint8Array(w*h);
  for(let i=0,p=0;i<img.data.length;i+=4,p++)gray[p]=(img.data[i]*77+img.data[i+1]*150+img.data[i+2]*29)>>8;
  const energy=(box)=>{let sum=0,count=0,x0=Math.max(1,Math.floor(box.x)),y0=Math.max(1,Math.floor(box.y)),x1=Math.min(w-1,Math.ceil(box.x+box.width)),y1=Math.min(h-1,Math.ceil(box.y+box.height));for(let y=y0;y<y1;y+=2)for(let x=x0;x<x1;x+=2){const p=y*w+x,gx=Math.abs(gray[p+1]-gray[p-1]),gy=Math.abs(gray[p+w]-gray[p-w]);sum+=gx+gy;count++}return count?sum/count:0};
  if(state.personModel){
    try{const people=(await state.personModel.detect(c,40,.22)).filter(x=>x.class==='person');if(people.length){let best=null;for(const person of people){const [x,y,width,height]=person.bbox,sharpness=energy({x,y,width,height}),area=Math.max(1,width*height),sizeBonus=Math.min(1,area/(w*h*.12)),score=sharpness*(.72+.28*person.score)*(.82+.18*sizeBonus),candidate={x,y,width,height,sharpness,score};if(!best||candidate.score>best.score)best=candidate}return{x:(best.x+best.width/2)/w,y:(best.y+best.height/2)/h,box:{x:best.x/w,y:best.y/h,w:best.width/w,h:best.height/h},sharpness:best.sharpness,method:`AI: nejostřejší z ${people.length} rozpoznaných postav`}}
    }catch(_){/* pokračuje místní záložní analýza */}
  }
  if('FaceDetector' in window){
    try{state.detector=state.detector||new FaceDetector({fastMode:true,maxDetectedFaces:30});const faces=await state.detector.detect(c);if(faces.length){let best=null;for(const face of faces){const b=face.boundingBox,pad=Math.max(b.width,b.height)*.45,box={x:b.x-pad,y:b.y-pad,width:b.width+2*pad,height:b.height+2*pad};box.score=energy(box);if(!best||box.score>best.score)best=box}const face=best,body={x:Math.max(0,face.x-face.width*.65),y:Math.max(0,face.y-face.height*.3),width:Math.min(w,face.width*2.3),height:Math.min(h,face.height*5.5)};body.width=Math.min(body.width,w-body.x);body.height=Math.min(body.height,h-body.y);return{x:(body.x+body.width/2)/w,y:(body.y+body.height/2)/h,box:{x:body.x/w,y:body.y/h,w:body.width/w,h:body.height/h},sharpness:face.score,method:`Nejostřejší z ${faces.length} rozpoznaných obličejů`}}
    }catch(_){state.detector=null}
  }
  const cols=12,rows=12,tw=w/cols,th=h/rows,candidates=[];
  for(let yy=0;yy<rows;yy++)for(let xx=0;xx<cols;xx++){const x=(xx+.5)*tw,y=(yy+.5)*th,center=1-.18*Math.hypot(x/w-.5,y/h-.5),score=energy({x:xx*tw,y:yy*th,width:tw,height:th})*center;candidates.push({x,y,score})}
  candidates.sort((a,b)=>b.score-a.score);const top=candidates.slice(0,Math.max(5,Math.round(candidates.length*.07)));let sx=0,sy=0,sw=0;top.forEach(p=>{const weight=Math.max(.01,p.score);sx+=p.x*weight;sy+=p.y*weight;sw+=weight});const fx=sx/sw,fy=sy/sw,bw=w*.58,bh=h*.78,bx=Math.max(0,Math.min(w-bw,fx-bw/2)),by=Math.max(0,Math.min(h-bh,fy-bh/2));return{x:fx/w,y:fy/h,box:{x:bx/w,y:by/h,w:bw/w,h:bh/h},sharpness:top[0]?.score||0,method:'Záloha: nejostřejší oblast fotografie'};
}

function renderEditor(){
  const item=current(),bmp=state.bitmap,canvas=$('#canvas');if(!item||!bmp)return;const maxW=Math.min(1050,$('.canvas-wrap').clientWidth||1050),maxH=680,scale=Math.min(maxW/bmp.width,maxH/bmp.height,1),cw=Math.max(1,Math.round(bmp.width*scale)),ch=Math.max(1,Math.round(bmp.height*scale));canvas.width=cw;canvas.height=ch;canvas.style.width=cw+'px';canvas.style.height=ch+'px';
  const ctx=canvas.getContext('2d');ctx.drawImage(bmp,0,0,cw,ch);state.view={scale};if(!item.crop){$('#methodBadge').textContent='Čeká na automatický ořez';return}
  const c=item.crop,x=c.x*scale,y=c.y*scale,w=c.w*scale,h=c.h*scale;ctx.save();ctx.fillStyle='rgba(0,0,0,.5)';ctx.beginPath();ctx.rect(0,0,cw,ch);ctx.rect(x,y,w,h);ctx.fill('evenodd');ctx.strokeStyle='#38bdf8';ctx.lineWidth=4;ctx.strokeRect(x+2,y+2,Math.max(0,w-4),Math.max(0,h-4));ctx.strokeStyle='rgba(255,255,255,.8)';ctx.lineWidth=1;for(let i=1;i<3;i++){ctx.beginPath();ctx.moveTo(x+w*i/3,y);ctx.lineTo(x+w*i/3,y+h);ctx.stroke();ctx.beginPath();ctx.moveTo(x,y+h*i/3);ctx.lineTo(x+w,y+h*i/3);ctx.stroke()}ctx.restore();$('#methodBadge').textContent=item.method;
}

const canvas=$('#canvas');canvas.onpointerdown=e=>{const item=current();if(!item?.crop||!state.view)return;const r=canvas.getBoundingClientRect(),sx=canvas.width/r.width,sy=canvas.height/r.height,px=(e.clientX-r.left)*sx/state.view.scale,py=(e.clientY-r.top)*sy/state.view.scale,c=item.crop;if(px<c.x||px>c.x+c.w||py<c.y||py>c.y+c.h)return;state.drag={px,py,x:c.x,y:c.y};canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging')};
canvas.onpointermove=e=>{if(!state.drag)return;const item=current(),r=canvas.getBoundingClientRect(),sx=canvas.width/r.width,sy=canvas.height/r.height,px=(e.clientX-r.left)*sx/state.view.scale,py=(e.clientY-r.top)*sy/state.view.scale;item.crop.x=state.drag.x+(px-state.drag.px);item.crop.y=state.drag.y+(py-state.drag.py);clampCrop(item.crop,item.width,item.height);renderEditor()};
canvas.onpointerup=canvas.onpointercancel=e=>{state.drag=null;canvas.classList.remove('dragging');try{canvas.releasePointerCapture(e.pointerId)}catch(_){}};
window.onresize=()=>{if(state.bitmap)renderEditor()};

async function makeOutput(item){
  const bitmap=await loadBitmap(item.file);try{const out=document.createElement('canvas'),c=item.crop;out.width=Math.max(1,Math.round(c.w));out.height=Math.max(1,Math.round(c.h));const ctx=out.getContext('2d',{willReadFrequently:true});ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(bitmap,c.x,c.y,c.w,c.h,0,0,out.width,out.height);autoEnhanceColors(ctx,out.width,out.height);sharpenCanvas(out,ctx,item);const blob=await new Promise((resolve,reject)=>out.toBlob(b=>b?resolve(b):reject(new Error('jpeg')),'image/jpeg',1));return await setJpegDpi(blob,300)}finally{if(bitmap.close)bitmap.close()}
}
async function makePreview(processedBlob,item){
  if(!state.watermarkSource)throw new Error('watermark_missing');
  const photo=await loadBitmap(processedBlob),logo=state.watermarkSource instanceof Blob?await loadBitmap(state.watermarkSource):state.watermarkSource;
  try{
    const scale=800/Math.max(photo.width,photo.height),w=Math.max(1,Math.round(photo.width*scale)),h=Math.max(1,Math.round(photo.height*scale));
    const out=document.createElement('canvas');out.width=w;out.height=h;const ctx=out.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(photo,0,0,w,h);
    const logoScale=Math.min(w*.145/logo.width,h*.105/logo.height,.25),lw=Math.max(1,Math.round(logo.width*logoScale)),lh=Math.max(1,Math.round(logo.height*logoScale));
    ctx.save();ctx.globalAlpha=.19;ctx.drawImage(logo,Math.round((w-lw)/2),Math.round((h-lh)/2),lw,lh);ctx.restore();
    const label=outputName(item),fontSize=Math.max(24,Math.round(w*.043)),pad=Math.max(9,Math.round(fontSize*.42)),barH=fontSize+pad*2;
    const drawMarkText=(value,y,baseline)=>{let size=Math.max(21,Math.round(Math.max(w,h)*.05));ctx.font=`900 ${size}px Arial, sans-serif`;const maxWidth=w*.90,measured=ctx.measureText(value).width;if(measured>maxWidth){size=Math.max(14,Math.floor(size*maxWidth/measured));ctx.font=`900 ${size}px Arial, sans-serif`}ctx.save();ctx.globalAlpha=.78;ctx.textAlign='center';ctx.textBaseline=baseline;ctx.lineJoin='round';ctx.lineWidth=Math.max(2,Math.round(size*.10));ctx.strokeStyle='#000';ctx.strokeText(value,w/2,y,maxWidth);ctx.fillStyle='#fff';ctx.fillText(value,w/2,y,maxWidth);ctx.restore()};
    drawMarkText('NEPRODEJNÁ KOPIE',Math.max(16,Math.round(h*.035)),'top');
    drawMarkText('www.fotozababku.cz',h-barH-Math.max(14,Math.round(h*.025)),'bottom');
    ctx.fillStyle='rgba(255,255,255,.88)';ctx.fillRect(0,h-barH,w,barH);ctx.font=`900 ${fontSize}px Arial, sans-serif`;ctx.textAlign='center';ctx.textBaseline='bottom';ctx.lineWidth=Math.max(3,Math.round(fontSize*.12));ctx.strokeStyle='#fff';ctx.strokeText(label,w/2,h-pad,w-pad*2);ctx.fillStyle='#e00000';ctx.fillText(label,w/2,h-pad,w-pad*2);
    return await new Promise((resolve,reject)=>out.toBlob(blob=>blob?resolve(blob):reject(new Error('preview_jpeg')),'image/jpeg',.90));
  }finally{photo.close?.();if(logo!==state.watermarkSource)logo.close?.()}
}
async function saveOutputs(folders,item){
  const processed=await makeOutput(item),preview=await makePreview(processed,item);
  if(window.desktopFiles){const [originalsRoot,originalsSub]=folders.originals.split('|'),[previewsRoot,previewsSub]=folders.previews.split('|');await window.desktopFiles.writeFile(originalsRoot,originalsSub,outputName(item),await processed.arrayBuffer());await window.desktopFiles.writeFile(previewsRoot,previewsSub,outputName(item),await preview.arrayBuffer());return}
  await writeToDirectory(folders.originals,item,processed);await writeToDirectory(folders.previews,item,preview);
}
function percentile(hist,total,fraction){let sum=0,target=total*fraction;for(let i=0;i<256;i++){sum+=hist[i];if(sum>=target)return i}return fraction<.5?0:255}
function autoEnhanceColors(ctx,w,h){
  const image=ctx.getImageData(0,0,w,h),d=image.data,hists=[new Uint32Array(256),new Uint32Array(256),new Uint32Array(256)];let samples=0;
  for(let i=0;i<d.length;i+=16){hists[0][d[i]]++;hists[1][d[i+1]]++;hists[2][d[i+2]]++;samples++}const low=hists.map(h=>percentile(h,samples,.008)),high=hists.map(h=>percentile(h,samples,.992));
  for(let i=0;i<d.length;i+=4){let rgb=[d[i],d[i+1],d[i+2]];for(let c=0;c<3;c++){const mapped=(rgb[c]-low[c])*255/Math.max(20,high[c]-low[c]);rgb[c]=rgb[c]*.38+Math.max(0,Math.min(255,mapped))*.62}const l=.299*rgb[0]+.587*rgb[1]+.114*rgb[2];d[i]=Math.max(0,Math.min(255,l+(rgb[0]-l)*1.07));d[i+1]=Math.max(0,Math.min(255,l+(rgb[1]-l)*1.07));d[i+2]=Math.max(0,Math.min(255,l+(rgb[2]-l)*1.07))}ctx.putImageData(image,0,0)
}
function sharpenCanvas(canvas,ctx,item){
  const w=canvas.width,h=canvas.height,original=ctx.getImageData(0,0,w,h),blur=document.createElement('canvas');blur.width=w;blur.height=h;const bctx=blur.getContext('2d',{willReadFrequently:true});bctx.filter='blur(1.15px)';bctx.drawImage(canvas,0,0);const softened=bctx.getImageData(0,0,w,h).data,d=original.data,amount=(item.sharpness||40)<24?.62:.42;
  let region=null;if(item.personBox){const p=item.personBox,c=item.crop;region={x:(p.x-c.x)/c.w*w,y:(p.y-c.y)/c.h*h,w:p.w/c.w*w,h:p.h/c.h*h};region.fx=Math.max(30,region.w*.12);region.fy=Math.max(30,region.h*.08)}
  for(let y=0,i=0;y<h;y++)for(let x=0;x<w;x++,i+=4){let mask=1;if(region){const mx=Math.max(0,Math.min(1,(x-region.x+region.fx)/region.fx,(region.x+region.w+region.fx-x)/region.fx)),my=Math.max(0,Math.min(1,(y-region.y+region.fy)/region.fy,(region.y+region.h+region.fy-y)/region.fy));mask=mx*my}const strength=.10+amount*mask;d[i]=Math.max(0,Math.min(255,d[i]+strength*(d[i]-softened[i])));d[i+1]=Math.max(0,Math.min(255,d[i+1]+strength*(d[i+1]-softened[i+1])));d[i+2]=Math.max(0,Math.min(255,d[i+2]+strength*(d[i+2]-softened[i+2])))}ctx.putImageData(original,0,0)
}
async function setJpegDpi(blob,dpi){const bytes=new Uint8Array(await blob.arrayBuffer());if(bytes.length>18&&bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff&&bytes[3]===0xe0&&String.fromCharCode(...bytes.slice(6,11))==='JFIF\0'){bytes[13]=1;bytes[14]=(dpi>>8)&255;bytes[15]=dpi&255;bytes[16]=(dpi>>8)&255;bytes[17]=dpi&255;return new Blob([bytes],{type:'image/jpeg'})}return blob}
async function saveCurrent(){const item=current();if(!item?.crop)return alert('Nejdříve připravte automatický ořez.');if(!state.watermarkSource)return alert('Logo vodoznaku není načtené. Vyberte jej prosím ručně.');const folders=await getOutputFolders();if(!folders)return;$('#saveOne').disabled=true;setStatus('Připravuji originál a náhled '+outputName(item)+'…');try{await saveOutputs(folders,item);setStatus('Uloženo: upravený originál a náhled do zvolených složek.')}catch(err){alert(err.message==='watermark_missing'?'Nejdříve vyberte logo vodoznaku.':'Fotografii a její náhled se nepodařilo uložit.')}finally{$('#saveOne').disabled=false}}
async function saveAll(){
  const ready=state.items.filter(x=>x.crop&&x.status==='ok');if(!ready.length)return alert('Nejdříve připravte automatický ořez.');if(!state.watermarkSource)return alert('Logo vodoznaku není načtené. Vyberte jej prosím ručně.');const folders=await getOutputFolders();if(!folders)return;$('#saveAll').disabled=true;$('#analyze').disabled=true;let saved=0;
  try{
    for(let i=0;i<ready.length;i++){const item=ready[i];setStatus(`Ukládám originál a náhled ${i+1} z ${ready.length}: ${outputName(item)}`);await saveOutputs(folders,item);saved++}
    setStatus(`Hotovo. Upravené originály a náhledy byly uloženy přímo do zvolených složek. Počet: ${saved}.`);
  }catch(err){setStatus(`Uloženo ${saved} fotografií. Další ukládání se nezdařilo.`);alert('Ukládání bylo přerušeno: '+(err.message||'chyba'))}finally{$('#saveAll').disabled=false;$('#analyze').disabled=false}
}
